import {problems, patterns, lessons, questions} from './data.js';
import {STORAGE_KEY, emptyState, validateState, reviewProblem, isDue, streak, dateKey, filterProblems} from './core.js';

const icons = {
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',
 sheet:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',
 pattern:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M9 6h6a3 3 0 0 1 3 3v6M6 9v6a3 3 0 0 0 3 3h6"/>',
 review:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2"/>',
 system:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="8" height="6" rx="1"/><rect x="14" y="16" width="8" height="6" rx="1"/><path d="M12 8v4H6v4m6-4h6v4"/>',
 chat:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 1-7a8 8 0 0 1-1-4 9 9 0 0 1 19 0Z"/><path d="M7 9h9M7 13h5"/>',
 chart:'<path d="M4 3v17h17M8 16v-5M13 16V7M18 16V4"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',
 external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 book:'<path d="M12 5c-3-3-7-3-10-1v15c3-2 7-2 10 1 3-3 7-3 10-1V4c-3-2-7-2-10 1Zm0 0v15"/>',
 flame:'<path d="M13 2c2 7-4 7-1 12 1-2 3-2 3-5 8 8 4 13-3 13S1 15 7 8c0 4 2 4 2 4-1-5 2-6 4-10Z"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8L21 9h-8z"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'), dialog=document.querySelector('#detail');
let state=emptyState(), storageAvailable=true;
try {const saved=localStorage.getItem(STORAGE_KEY); if(saved)state=validateState(JSON.parse(saved),problems.map(p=>p.id),lessons.map(l=>l.id),questions.map(q=>q.id));} catch {storageAvailable=false;}
let page=location.hash.slice(1)||'today', query='', pattern='All patterns', difficulty='All levels', status='All progress', reviewSession=false, revealed=false, deferredInstall=null;
const navs=[['today','home','Overview'],['sheet','sheet','DSA sheet'],['patterns','pattern','Pattern library'],['review','review','Review queue'],['system','system','System design'],['interview','chat','Interview questions'],['progress','chart','My progress']];
const progress=id=>state.problems[id]||{status:'todo',starred:false,notes:'',reviews:0};
const solved=()=>problems.filter(p=>progress(p.id).status==='solved').length;
const due=()=>problems.filter(p=>isDue(progress(p.id))).sort((a,b)=>progress(a.id).due-progress(b.id).due);
const touch=()=>{const today=dateKey();if(!state.activity.includes(today))state.activity.push(today);};
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast('Your browser could not save progress. Export a backup from My progress.');}}
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
function navigate(next){page=navs.some(n=>n[0]===next)?next:'today';location.hash=page;render();document.querySelector('#main').focus();}
function statusBadge(id){const s=progress(id).status;return `<span class="status ${s}">${s==='solved'?icon('check')+'Solved':s==='learning'?'In progress':'Not started'}</span>`;}
function problemRow(p){return `<div class="problem-row"><button class="bookmark ${progress(p.id).starred?'is-starred':''}" data-star="${p.id}" aria-label="${progress(p.id).starred?'Remove bookmark for':'Bookmark'} ${esc(p.title)}" aria-pressed="${progress(p.id).starred}">${icon('star')}</button><button class="problem-name" data-problem="${p.id}"><span>${esc(p.title)}</span><small>${esc(p.pattern)}</small></button><span class="difficulty ${p.difficulty.toLowerCase()}">${p.difficulty}</span><span class="row-status">${statusBadge(p.id)}</span><a class="source-link" href="${p.url}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(p.title)} on LeetCode">${icon('external')}</a></div>`;}
function header(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function sectionTitle(title,right=''){return `<div class="section-heading"><h2>${title}</h2>${right}</div>`;}
function patternVisual(){return `<div class="pattern-visual" aria-label="Two pointers move inward through a sorted array"><div class="visual-label"><span>Two pointers</span><span class="tiny-pill">Pattern #02</span></div><div class="pointer-labels"><span>left</span><span>right</span></div><div class="array">${[1,2,4,6,8].map((n,i)=>`<span class="${i===0||i===4?'active':''}">${n}</span>`).join('')}</div><div class="pointer-track"><span>↳</span><span class="dotted"></span><span>↲</span></div><p>Less guessing. More patterns.</p></div>`;}
function overview(){const next=problems.filter(p=>progress(p.id).status!=='solved').slice(0,3),remaining=due().length,completed=solved();return `${header('A little practice. A lot more confidence.','Your next interview starts with what you practice today.',`<span class="date-label">${new Intl.DateTimeFormat('en',{month:'short',day:'numeric',weekday:'short'}).format(new Date())}</span>`)}
 <section class="hero"><div class="hero-copy"><span class="hero-tag">Your interview practice space</span><h2>Learn the pattern.<br>Make it second nature.</h2><p>Build understanding that stays with you.<br>One problem, one connection, one day at a time.</p><button class="primary" data-problem="${next[0]?.id||problems[0].id}">Continue practicing ${icon('arrow')}</button><span class="hero-foot">${icon('check')} Your progress stays on this device</span></div>${patternVisual()}</section>
 <div class="stats"><article><span class="stat-icon violet">${icon('sheet')}</span><div><span class="stat-number">${completed}<small> / ${problems.length}</small></span><p>Problems solved</p></div><span class="stat-end">${Math.round(completed/problems.length*100)}%</span></article><article><span class="stat-icon amber">${icon('flame')}</span><div><span class="stat-number">${streak(state.activity)}<small> days</small></span><p>Current streak</p></div></article><article><span class="stat-icon mint">${icon('review')}</span><div><span class="stat-number">${remaining}<small> problems</small></span><p>Ready for review</p></div><button class="icon-button" data-nav="review" aria-label="View review queue">${icon('arrow')}</button></article></div>
 <div class="overview-columns"><section class="panel practice-panel">${sectionTitle('Your next steps',`<button class="text-button" data-nav="sheet">View full sheet ${icon('arrow')}</button>`)}<p class="section-subtitle">A focused session starts with a small, doable list.</p><div class="practice-list">${next.length?next.map((p,i)=>`<button class="practice-item" data-problem="${p.id}"><span class="step-number">${i+1}</span><span class="practice-title">${p.title}<small>${p.pattern}</small></span><span class="difficulty ${p.difficulty.toLowerCase()}">${p.difficulty}</span>${icon('arrow')}</button>`).join(''):'<p class="empty">You have solved the whole starter sheet. Keep it fresh with spaced reviews.</p>'}</div><div class="session-tip">${icon('bolt')}<p>Try explaining your approach out loud before you code.</p></div></section>
 <aside class="panel review-panel"><span class="soft-icon">${icon('review')}</span><h2>Remember more.<br>Relearn less.</h2><p>${remaining?`${remaining} problems are ready for another look. A quick recall session will help them stick.`:'Solve a problem, then rate your recall. We’ll bring it back at the right time.'}</p><button class="secondary" data-nav="review">${remaining?'Start a review':'Explore your review queue'} ${icon('arrow')}</button><small>Spaced practice, built into your routine.</small></aside></div>
 <section class="explore">${sectionTitle('Build your interview toolkit')}<div class="toolkit"><button data-nav="patterns"><span class="toolkit-icon violet">${icon('pattern')}</span><div><h3>Think in patterns</h3><p>Recognize the idea behind the problem.</p></div>${icon('arrow')}</button><button data-nav="system"><span class="toolkit-icon blue">${icon('system')}</span><div><h3>See the bigger picture</h3><p>Design systems. Explain your tradeoffs.</p></div>${icon('arrow')}</button></div></section>`;}
function sheet(){const list=filterProblems(problems,state.problems,{query,pattern,difficulty,status});return `${header('Your DSA practice sheet',`${problems.length} carefully chosen problems. Understand the approach, then make it your own.`,`<button class="secondary" data-nav="patterns">${icon('pattern')} Explore patterns</button>`)}<div class="sheet-banner"><div><strong>Understanding over memorization.</strong><p>Recall the idea before revealing the solution. That’s where the learning happens.</p></div><span>${solved()} of ${problems.length} solved</span></div><div class="filters"><label class="search">${icon('search')}<input id="problem-search" type="search" placeholder="Search problems or patterns…" value="${esc(query)}" aria-label="Search problems"></label>${select('pattern',patterns,'All patterns',pattern)}${select('difficulty',['Easy','Medium','Hard'],'All levels',difficulty)}${select('status',['todo','learning','solved','Bookmarked','Due for review'],'All progress',status)}</div><div class="table-panel"><div class="table-caption"><strong>${list.length} problems</strong><span>Original summaries · Questions on LeetCode</span></div><div class="table-head"><span>Problem</span><span>Difficulty</span><span>Progress</span><span>Source</span></div><div id="problem-list">${list.length?list.map(problemRow).join(''):`<div class="empty"><h3>No problems match those filters.</h3><p>Try a different search or reset the filters.</p><button class="secondary" data-reset-filters>Reset filters</button></div>`}</div></div>`;}
function select(id,items,all,current){const labels={todo:'Not started',learning:'In progress',solved:'Solved'};return `<label class="sr-only" for="filter-${id}">Filter by ${id}</label><select id="filter-${id}"><option>${all}</option>${items.map(x=>`<option value="${x}" ${current===x?'selected':''}>${labels[x]||x}</option>`).join('')}</select>`;}
function patternPage(){return `${header('See the pattern. Find the approach.','Connect familiar clues to a technique you can explain.')}<div class="pattern-grid">${patterns.map((name,i)=>{const ps=problems.filter(p=>p.pattern===name),done=ps.filter(p=>progress(p.id).status==='solved').length;return `<article class="panel pattern-card"><div class="pattern-card-top"><span class="pattern-glyph">${icon(i%2?'pattern':'sheet')}</span><span>${done}/${ps.length} solved</span></div><h2>${name}</h2><p>${esc(ps[0].cue)}</p><div class="mini-progress"><span style="width:${done/ps.length*100}%"></span></div><button class="text-button" data-pattern="${name}">Practice ${ps.length} problems ${icon('arrow')}</button><details><summary>Recognize this pattern</summary><p>${esc(ps[0].solution)}</p><strong>Ask yourself</strong><p>${esc(ps[0].recall)}</p></details></article>`;}).join('')}</div>`;}
function reviewPage(){const list=due(),scheduled=problems.filter(p=>progress(p.id).due&&!isDue(progress(p.id))).sort((a,b)=>progress(a.id).due-progress(b.id).due);return `${header('Keep what you’ve learned.','Retrieve the idea from memory. Then check it, rate it, and revisit it.')}<section class="review-intro"><span class="soft-icon">${icon('review')}</span><div><h2>${list.length?`${list.length} problems ready for recall`:'You’re all caught up.'}</h2><p>${list.length?'Don’t peek yet. Explain the approach and its complexity before revealing the summary.':'Your next review starts after you rate a solution. New here? Pick a problem to get started.'}</p></div><button class="primary" ${list.length?`data-review="${list[0].id}"`:'data-nav="sheet"'}>${list.length?'Begin review':'Choose a problem'} ${icon('arrow')}</button></section>${list.length?`<div class="table-panel">${list.map(p=>`<div class="queue-row"><div><strong>${esc(p.title)}</strong><small>${p.pattern}</small></div><span class="difficulty ${p.difficulty.toLowerCase()}">${p.difficulty}</span><button class="secondary" data-review="${p.id}">Recall solution ${icon('arrow')}</button></div>`).join('')}</div>`:''}${sectionTitle('Coming up next')}<div class="panel upcoming">${scheduled.length?scheduled.map(p=>`<div><span>${p.title}</span><time>${new Intl.DateTimeFormat('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(progress(p.id).due))}</time></div>`).join(''):'<p>No reviews scheduled yet. Open a problem, reveal its solution, and rate your recall.</p>'}</div><div class="method-note"><h3>How the review loop works</h3><p><strong>Again</strong> brings it back in 10 minutes. <strong>Hard</strong> schedules tomorrow. <strong>Good</strong> starts at 3 days, <strong>Easy</strong> at 7. Successful repeat reviews increase the interval. These are simple study intervals, not a scientific measure of mastery.</p></div>`;}
function systemPage(){return `${header('Think beyond a single function.','Learn the building blocks, then explain the choices in a real design.')}<div class="system-banner"><div><span class="hero-tag">A framework you can reuse</span><h2>Requirements. Scale. Tradeoffs.</h2><p>Start with the problem. Draw the simplest useful system.<br>Then find the part that breaks first.</p></div><div class="architecture"><span>Client</span><i>→</i><span>API</span><i>→</i><span>Cache<br><small>Database</small></span></div></div><div class="lesson-list">${lessons.map((l,i)=>`<button class="lesson-row panel" data-lesson="${l.id}"><span class="lesson-index ${state.lessons[l.id]?'complete':''}">${state.lessons[l.id]?icon('check'):String(i+1).padStart(2,'0')}</span><div><span class="lesson-category">${l.category}</span><h2>${l.title}</h2><p>${l.summary}</p></div><span class="lesson-time">${icon('clock')}${l.minutes} min</span>${icon('arrow')}</button>`).join('')}</div><p class="content-note">Original introductory lessons. For deeper study, each lesson links to the open-source System Design Primer.</p>`;}
function interviewPage(){return `${header('Practice the explanation, too.','Build clear answers to technical and behavioral interview questions.')}<div class="interview-note">${icon('chat')}<p>Say your answer aloud first. Save a few notes, then compare with the checkpoints.</p></div><div class="question-grid">${questions.map(q=>`<article class="panel question-card"><span class="category-label">${q.category}</span><h2>${q.title}</h2><p>${q.hint}</p><label for="answer-${q.id}">Your talking points</label><textarea id="answer-${q.id}" data-answer="${q.id}" placeholder="Outline your answer…" maxlength="10000">${esc(state.answers[q.id]||'')}</textarea><details><summary>Show answer checkpoints</summary><p>${q.check}</p></details></article>`).join('')}</div>`;}
function progressPage(){const totalReviews=Object.values(state.problems).reduce((n,p)=>n+(p.reviews||0),0),learning=problems.filter(p=>progress(p.id).status==='learning').length;return `${header('Progress you can build on.','A record of your practice, saved in this browser.',`<button class="secondary" data-export>${icon('download')} Export progress</button>`)}<div class="stats"><article><span class="stat-icon violet">${icon('check')}</span><div><span class="stat-number">${solved()}</span><p>Problems solved</p></div></article><article><span class="stat-icon mint">${icon('review')}</span><div><span class="stat-number">${totalReviews}</span><p>Recall ratings logged</p></div></article><article><span class="stat-icon amber">${icon('book')}</span><div><span class="stat-number">${Object.values(state.lessons).filter(Boolean).length}<small> / ${lessons.length}</small></span><p>Design lessons completed</p></div></article></div><div class="progress-columns"><section class="panel"><h2>Your pattern coverage</h2><p class="section-subtitle">Solved problems by technique.</p>${patterns.map(name=>{const ps=problems.filter(p=>p.pattern===name),done=ps.filter(p=>progress(p.id).status==='solved').length;return `<div class="coverage-row"><div><span>${name}</span><small>${done} / ${ps.length}</small></div><div class="mini-progress"><span style="width:${done/ps.length*100}%"></span></div></div>`;}).join('')}</section><div><section class="panel activity-panel"><h2>Your last 28 days</h2><div class="activity-grid">${Array.from({length:28},(_,i)=>{const d=new Date();d.setDate(d.getDate()-27+i);const active=state.activity.includes(dateKey(d));return `<span class="${active?'active':''}" title="${dateKey(d)}: ${active?'Practiced':'No practice logged'}"><span class="sr-only">${dateKey(d)}: ${active?'Practiced':'No practice logged'}</span></span>`;}).join('')}</div><p>${streak(state.activity)} day streak · ${learning} problems in progress</p></section><section class="panel backup-panel"><h2>Your work belongs to you.</h2><p>Progress is stored on this device. Export a backup before changing browsers or clearing browser data.</p><button class="secondary" data-export>${icon('download')} Export backup</button><label class="import-button">Import backup<input type="file" id="import" accept="application/json,.json"></label><p class="small-text">Import merges with current progress. Matching items use the backup’s values. No account or cloud sync in this release.</p></section></div></div>`;}
function render(){if(!navs.some(n=>n[0]===page))page='today';app.innerHTML=`<aside class="sidebar"><a class="brand" href="#today"><img src="./icon.svg" alt="" width="34" height="34"><span>recall<span class="brand-dot">.</span></span></a><span class="workspace-label">Your practice workspace</span><nav aria-label="Main navigation">${navs.map(([id,ic,label],i)=>`${i===4?'<div class="nav-divider"><span>Beyond the code</span></div>':''}<button class="nav-item ${page===id?'selected':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='review'&&due().length?`<span class="nav-count">${due().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="daily-note"><span>Small steps. Strong foundations.</span><p>You don’t have to learn it all today.<br>Just keep coming back.</p><div class="note-line"></div></div><button class="install-button" data-install>${icon('download')} Install Recall</button><div class="local-profile"><span>Y</span><div>Your workspace<small>${storageAvailable?'Saved on this device':'Storage unavailable — export a backup'}</small></div><span class="online-dot ${navigator.onLine?'':'offline'}" title="${navigator.onLine?'Online':'Offline'}"></span></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" data-menu aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${navs.find(n=>n[0]===page)[2]}</strong></div><div class="topbar-right"><span class="offline-label">${navigator.onLine?'Offline-ready practice':'You’re offline'}</span><button class="search-shortcut" data-search aria-label="Search DSA problems">${icon('search')}<span>Find a problem</span><kbd>/</kbd></button><span class="avatar">Y</span></div></header><main id="main" tabindex="-1">${({today:overview,sheet,patterns:patternPage,review:reviewPage,system:systemPage,interview:interviewPage,progress:progressPage}[page])()}</main><footer><span>Built for understanding. Designed for the long run.</span><span>Recall · Starter edition</span></footer></div>`;}
function openProblem(id,review=false){const p=problems.find(p=>p.id===id);if(!p)return;reviewSession=review;revealed=false;dialog.dataset.problem=id;renderProblem(p);dialog.showModal();}
function renderProblem(p){const v=progress(p.id);dialog.innerHTML=`<div class="dialog-header"><span class="category-label">${reviewSession?'Active recall':'DSA practice'} · ${p.pattern}</span><button class="icon-button" data-close aria-label="Close problem">${icon('close')}</button></div><h2 id="dialog-title">${p.title}</h2><div class="dialog-meta"><span class="difficulty ${p.difficulty.toLowerCase()}">${p.difficulty}</span><a href="${p.url}" target="_blank" rel="noopener noreferrer">Open question on LeetCode ${icon('external')}</a></div><div class="recall-prompt"><span>${icon('bolt')} Before you reveal</span><h3>${esc(p.recall)}</h3><p>Explain your approach and complexity out loud, or sketch it in your notes.</p></div>${revealed?`<section class="solution"><h3>The core idea</h3><div class="memory-cue">${esc(p.cue)}</div><p>${esc(p.solution)}</p><div class="complexity"><span>Time <strong>${p.time}</strong></span><span>Space <strong>${p.space}</strong></span></div></section><section class="rating"><h3>How well did you recall it?</h3><p>Your rating schedules the next review.</p><div class="rating-buttons"><button data-rating="again"><strong>Again</strong><small>10 minutes</small></button><button data-rating="hard"><strong>Hard</strong><small>1 day</small></button><button data-rating="good"><strong>Good</strong><small>${Math.max(3,Math.min(180,(v.interval||0)*2))} days</small></button><button data-rating="easy"><strong>Easy</strong><small>${Math.max(7,Math.min(365,(v.interval||0)*3))} days</small></button></div></section>`:`<button class="primary reveal-button" data-reveal>${icon('book')} Reveal solution & memory cue</button>`}<label class="notes-label" for="problem-notes">My notes <span>Saved as you type</span></label><textarea id="problem-notes" maxlength="10000" placeholder="The clue I missed, a useful example, or a simpler explanation…">${esc(v.notes)}</textarea><div class="dialog-footer"><label for="problem-status">Progress <select id="problem-status"><option value="todo" ${v.status==='todo'?'selected':''}>Not started</option><option value="learning" ${v.status==='learning'?'selected':''}>In progress</option><option value="solved" ${v.status==='solved'?'selected':''}>Solved</option></select></label><button class="text-button ${v.starred?'is-starred':''}" data-star="${p.id}">${icon('star')} ${v.starred?'Bookmarked':'Bookmark'}</button></div>`;}
function openLesson(id){const l=lessons.find(l=>l.id===id);dialog.removeAttribute('data-problem');dialog.innerHTML=`<div class="dialog-header"><span class="category-label">${l.category} · ${l.minutes} min</span><button class="icon-button" data-close aria-label="Close lesson">${icon('close')}</button></div><h2 id="dialog-title">${l.title}</h2><p class="lesson-summary">${l.summary}</p><div class="recall-prompt"><span>${icon('chat')} Interview prompt</span><h3>${l.prompt}</h3></div><h3>Build your explanation</h3><ol class="lesson-points">${l.points.map(s=>`<li>${s}</li>`).join('')}</ol><div class="tradeoff"><h3>The tradeoff to explain</h3><p>${l.tradeoff}</p></div><div class="memory-cue">${l.cue}</div><div class="lesson-actions"><a class="secondary" href="${l.source}" target="_blank" rel="noopener noreferrer">Read more ${icon('external')}</a><button class="primary" data-complete-lesson="${id}">${state.lessons[id]?'Mark as incomplete':'Mark lesson complete'} ${icon('check')}</button></div>`;dialog.showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,label');if(!b)return;
 if(b.hasAttribute('data-nav'))navigate(b.dataset.nav);
 else if(b.hasAttribute('data-problem'))openProblem(b.dataset.problem);
 else if(b.hasAttribute('data-review'))openProblem(b.dataset.review,true);
 else if(b.hasAttribute('data-close'))dialog.close();
 else if(b.hasAttribute('data-reveal')){revealed=true;renderProblem(problems.find(p=>p.id===dialog.dataset.problem));}
 else if(b.hasAttribute('data-rating')){const id=dialog.dataset.problem;state.problems[id]=reviewProblem(progress(id),b.dataset.rating);touch();save();dialog.close();render();toast(b.dataset.rating==='again'?'Scheduled another try in 10 minutes.':'Progress saved. Your next review is scheduled.');}
 else if(b.hasAttribute('data-star')){const id=b.dataset.star;state.problems[id]={...progress(id),starred:!progress(id).starred};save();render();if(dialog.open&&dialog.dataset.problem===id)renderProblem(problems.find(p=>p.id===id));}
 else if(b.hasAttribute('data-pattern')){pattern=b.dataset.pattern;query='';status='All progress';difficulty='All levels';navigate('sheet');}
 else if(b.hasAttribute('data-reset-filters')){query='';pattern='All patterns';status='All progress';difficulty='All levels';render();}
 else if(b.hasAttribute('data-lesson'))openLesson(b.dataset.lesson);
 else if(b.hasAttribute('data-complete-lesson')){const id=b.dataset.completeLesson;state.lessons[id]=!state.lessons[id];touch();save();dialog.close();render();toast(state.lessons[id]?'Lesson completed. Keep explaining those tradeoffs.':'Lesson marked as incomplete.');}
 else if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`recall-progress-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup exported.');}
 else if(b.hasAttribute('data-search')){navigate('sheet');document.querySelector('#problem-search').focus();}
 else if(b.hasAttribute('data-menu'))document.querySelector('.sidebar').classList.toggle('mobile-open');
 else if(b.hasAttribute('data-install')){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;}else toast('Install from your browser’s menu. On iPhone: Share → Add to Home Screen.');}
});
document.addEventListener('input',e=>{if(e.target.id==='problem-search'){query=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#problem-search');input.focus();input.setSelectionRange(start,start);}
 if(e.target.id==='problem-notes'){const id=dialog.dataset.problem;state.problems[id]={...progress(id),notes:e.target.value};save();}
 if(e.target.dataset.answer){state.answers[e.target.dataset.answer]=e.target.value;touch();save();}
});
document.addEventListener('change',async e=>{const id=e.target.id;
 if(id.startsWith('filter-')){if(id==='filter-pattern')pattern=e.target.value;if(id==='filter-difficulty')difficulty=e.target.value;if(id==='filter-status')status=e.target.value;render();}
 if(id==='problem-status'){const p=dialog.dataset.problem;state.problems[p]={...progress(p),status:e.target.value};touch();save();render();toast('Progress saved. Rate your recall to schedule a review.');}
 if(id==='import'){const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Choose a backup smaller than 2 MB.');const raw=validateState(JSON.parse(await file.text()),problems.map(p=>p.id),lessons.map(l=>l.id),questions.map(q=>q.id));state={...state,problems:{...state.problems,...raw.problems},lessons:{...state.lessons,...raw.lessons},answers:{...state.answers,...raw.answers},activity:[...new Set([...state.activity,...raw.activity])].sort()};save();render();toast('Backup imported and merged with your progress.');}catch(error){toast(error instanceof SyntaxError?'This file is not valid JSON. Choose a Recall backup.':error.message);}}
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();navigate('sheet');document.querySelector('#problem-search').focus();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(page!==next){page=next;render();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
window.addEventListener('online',render);window.addEventListener('offline',render);
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup could not finish. Reconnect and reload to try again.'));
